<?php require __DIR__.'/app/layout.php';must_login();$id=(int)($_GET['id']??0);
$r=one_row('SELECT * FROM rooms WHERE id=?',[$id]);if(!$r){http_response_code(404);exit('Salle introuvable.');}
$next=all_rows("SELECT r.*,u.name AS organizer FROM reservations r JOIN users u ON u.id=r.user_id WHERE r.room_id=? AND r.status IN ('pending','approved') AND TIMESTAMP(r.booking_date,r.start_time)>=NOW() ORDER BY booking_date,start_time LIMIT 8",[$id]);
page_start('Détails de la salle','rooms'); titlebar('Détails','Salle '.$r['name'],'Équipements, capacité et créneaux déjà réservés.'); ?>
<div class="row g-4"><div class="col-lg-5"><div class="panel"><img class="room-cover mb-4" src="<?=h(room_image($r['image']))?>" alt="<?=h($r['name'])?>"><div class="d-flex justify-content-between"><h3><?=h($r['name'])?></h3><?=pill($r['status'])?></div><p class="muted"><?=nl2br(h($r['description']))?></p><p><i class="bi bi-people me-2 text-primary"></i><strong>Capacité :</strong> <?=h($r['capacity']??'À préciser')?></p><p><i class="bi bi-pin-map me-2 text-primary"></i><strong>Emplacement :</strong> <?=h($r['location']?:'Non précisé')?></p><p><i class="bi bi-tools me-2 text-primary"></i><strong>Équipements :</strong> <?=nl2br(h($r['equipment']?:'Non renseignés'))?></p><a class="btn btn-primary" href="<?=h(url('reservation.php?room_id='.$id))?>">Créer une réservation</a></div></div><div class="col-lg-7"><div class="panel"><div class="panel-head"><h3>Prochains créneaux occupés</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Horaire</th><th>Objet</th><th>Statut</th></tr></thead><tbody><?php foreach($next as $b):?><tr><td><?=h($b['booking_date'])?></td><td><?=h(substr($b['start_time'],0,5).' – '.substr($b['end_time'],0,5))?></td><td><?=h($b['title'])?></td><td><?=pill($b['status'])?></td></tr><?php endforeach;?><?php if(!$next):?><tr><td colspan="4" class="muted text-center py-4">Aucun créneau à venir.</td></tr><?php endif;?></tbody></table></div></div></div></div>
<?php page_end();?>
